select public.release_check(not has_table_privilege('authenticated','public.release_notice_state','select'), 'draft state is not directly readable');
select public.release_check(not has_table_privilege('authenticated','public.release_notice_events','insert'), 'audit is not caller writable');
select public.release_check(not has_function_privilege('anon','public.get_active_release_notice()','execute'), 'anonymous cannot read notices');
select public.release_check(not has_function_privilege('anon','public.update_release_notice(text,bigint,text,uuid)','execute'), 'anonymous cannot publish');

begin;
select set_config('request.jwt.claim.sub',public.release_test_id(3)::text,true);
set local role authenticated;
select public.release_check(public.get_active_release_notice()->'release'='null'::jsonb, 'no notice before publication');
do $$begin
  begin perform public.get_release_notice_admin(); raise exception 'ordinary user read admin draft'; exception when insufficient_privilege then null; end;
  begin perform public.update_release_notice('publish',0,'Unauthorized'); raise exception 'ordinary user published'; exception when insufficient_privilege then null; end;
  begin update public.release_notice_state set revision=100; raise exception 'direct state mutation'; exception when insufficient_privilege then null; end;
end $$;
select set_config('request.jwt.claim.sub',public.release_test_id(1)::text,true);
select public.release_check((public.update_release_notice('save',0,'Perbaikan: Draft belum diterbitkan')->>'revision')::int=1,'save increments revision');
select public.release_check(public.get_active_release_notice()->'release'='null'::jsonb,'saved draft stays private');
select public.release_check((public.update_release_notice('publish',1,E'Perbaikan: Isi editor belum disimpan\nPenambahan: Pengumuman mandiri')->'release'->'items'->>0)='Perbaikan: Isi editor belum disimpan','publish includes unsaved content atomically');
select public.release_check((public.get_active_release_notice()->'release'->>'expiresAt')::timestamptz=
  (date_trunc('day',(public.get_active_release_notice()->'release'->>'publishedAt')::timestamptz at time zone 'Asia/Jakarta')+interval '1 day') at time zone 'Asia/Jakarta', 'expiry is next midnight WIB');
select public.release_check((public.get_active_release_notice()->'release'->>'publishedAt')::timestamptz<=clock_timestamp(),'publication uses server clock');
reset role;
create temp table release_original as select active_release, (select after_state from public.release_notice_events where revision=2) audit from public.release_notice_state;
select set_config('request.jwt.claim.sub',public.release_test_id(3)::text,true);
set local role authenticated;
select public.dismiss_release_notice((public.get_active_release_notice()->'release'->>'id')::uuid);
select public.release_check((select dismissed_release_id::text from public.release_notice_preferences where user_id=auth.uid())=(public.get_active_release_notice()->'release'->>'id'),'explicit dismissal remains owner scoped');
select set_config('request.jwt.claim.sub',public.release_test_id(1)::text,true);
select public.update_release_notice('save',2,'Draft berikutnya');
reset role;
select public.release_check((select state.active_release=original.active_release from public.release_notice_state state cross join release_original original),'saving draft does not change active release');
select public.release_check((select event.after_state=original.audit from public.release_notice_events event cross join release_original original where event.revision=2),'published snapshot remains immutable');
set local role authenticated;
do $$begin
  begin perform public.update_release_notice('save',1,'Stale editor'); raise exception 'stale write accepted'; exception when serialization_failure then null; end;
  begin perform public.update_release_notice('withdraw',3,null,public.release_test_id(99)); raise exception 'wrong release withdrawn'; exception when serialization_failure then null; end;
  begin perform public.update_release_notice('publish',3,'   '); raise exception 'empty notice accepted'; exception when invalid_parameter_value then null; end;
  begin perform public.update_release_notice('publish',3,E'\t\t\t\t\t\n\t'); raise exception 'whitespace notice accepted'; exception when invalid_parameter_value then null; end;
  begin perform public.update_release_notice('save',3,repeat('x',1501)); raise exception 'oversize notice accepted'; exception when invalid_parameter_value then null; end;
  begin perform public.update_release_notice('publish',3,array_to_string(array_fill('Item'::text,array[11]),E'\n')); raise exception 'excess lines accepted'; exception when invalid_parameter_value then null; end;
  begin perform public.update_release_notice('invalid',3,'Invalid action'); raise exception 'invalid action accepted'; exception when invalid_parameter_value then null; end;
end $$;
select public.update_release_notice('publish',3,'Perbaikan: Publikasi kedua');
reset role;
select public.release_check((select state.active_release->>'id'<>original.active_release->>'id' from public.release_notice_state state cross join release_original original),'new publication has independent dismissal identity');
select set_config('request.jwt.claim.sub',public.release_test_id(1)::text,true);
set local role authenticated;
select public.update_release_notice('withdraw',4,null,(public.get_active_release_notice()->'release'->>'id')::uuid);
select public.release_check(public.get_active_release_notice()->'release'='null'::jsonb,'withdrawn notice is hidden without reviving old publication');
select public.release_check(public.get_release_notice_admin()->'history'->0->'release'->>'id' is not null,'withdrawn history keeps publication contents');
select public.update_release_notice('publish',5,'Perbaikan: Batas tengah malam');
reset role;
update public.release_notice_state set active_release=jsonb_set(active_release,'{expiresAt}',to_jsonb(clock_timestamp()-interval '1 second'));
select set_config('request.jwt.claim.sub',public.release_test_id(3)::text,true);
set local role authenticated;
select public.release_check(public.get_active_release_notice()->'release'='null'::jsonb,'expired notice is hidden');
select set_config('request.jwt.claim.sub',public.release_test_id(4)::text,true);
do $$begin begin perform public.update_release_notice('save',6,'Inactive admin'); raise exception 'inactive admin write accepted'; exception when insufficient_privilege then null; end; end $$;
select set_config('request.jwt.claim.sub',public.release_test_id(5)::text,true);
do $$begin begin perform public.get_active_release_notice(); raise exception 'deleted account read accepted'; exception when insufficient_privilege then null; end; end $$;
select set_config('request.jwt.claim.sub',public.release_test_id(99)::text,true);
do $$begin begin perform public.get_active_release_notice(); raise exception 'missing profile read accepted'; exception when insufficient_privilege then null; end; end $$;
rollback;
select public.release_check((select revision=0 and draft_content='' and active_release is null from public.release_notice_state),'all fixture actions rolled back');
select public.release_check((select count(*)=0 from public.release_notice_events),'no persistent publication from fixture assertions');
select public.release_check((select dismissed_release_id=public.release_test_id(90) from public.release_notice_preferences where user_id=public.release_test_id(3)),'legacy dismissal preserved');
select public.release_check((select status='completed' from public.maintenance_fixture),'maintenance lifecycle unchanged');
do $$begin raise notice 'Standalone release notice assertions passed';end $$;
